#!/usr/bin/env bash
#
# coverage_badge.sh - render the RELEASE coverage badge as a self-contained
# SVG committed to the repo (doc/badge/coverage.svg).
#
# The three properties of the badge: a committed SVG that loads nothing
# external, a value that carries the version it measures, and a figure over
# the Bash sources only. It is TO BE regenerated by the release bump. That
# caller does not exist yet (`docker_harness#289`). Until it lands this is
# a hand-run step.
#
# WHERE THE NUMBER COMES FROM: coverage_gate.sh's merge math over the kcov
# reports in <root>/coverage/.
#
# Refuses, writing nothing, unless coverage/.head-sha records HEAD's sha and
# `scope=full`, the reports are no older than HEAD, and no instrumented
# source is modified.
#
# Usage:
#   coverage_badge.sh [options]
#
# Options:
#   --repo-root <path>   Repo to render for (default: git toplevel of cwd).
#   --version <vX.Y.Z>   Version the figure belongs to (default: <root>/.version).
#   --out <path>         SVG to write (default: <root>/doc/badge/coverage.svg).
#   --report <path>      Cobertura report to read (repeatable). Default:
#                        discovered under <root>/coverage/.
#   --unmeasured         Render "not measured" for <version> instead of a
#                        figure. Never used by the release bump.
#   -h, --help           Show this help.
#
# Cadence:
#   The figure refreshes once per release, NEVER per merge: it answers "what
#   is the coverage of vX.Y.Z", a fact about a shipped artifact. It is
#   meant to ride the `chore: release vX.Y.Z` commit alongside `.version`
#   and the CHANGELOG promotion, so run it on the bump's working tree
#   BEFORE that commit is made -- afterwards HEAD is no longer the commit
#   the coverage run measured and this script refuses. Wiring it into the
#   harness release bump is tracked in docker_harness#289; until that
#   lands it is `just release coverage-badge`, run by hand at bump time.
#
# Exit:
#   0 = badge written
#   1 = refused (no usable measurement of the commit being released)
#   2 = arg / environment error

SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]:-$0}")" &> /dev/null && pwd)"
readonly SCRIPT_DIR

# The one implementation of the merge math.
readonly GATE="${SCRIPT_DIR}/../test/drivers/coverage_gate.sh"

readonly DEFAULT_OUT_REL="doc/badge/coverage.svg"

# Where `just test coverage` records the sha and scope it measured.
readonly HEAD_STAMP_REL="coverage/.head-sha"

# The remedy every refusal ends on. One unbroken line: coverage_badge_spec
# reads each line that names `just test coverage`.
readonly RERUN_HINT="Re-run \`just test coverage\` (or \`just test coverage-local\`, the same whole-suite measurement run as N parallel kcov processes) on the commit being released."

# Paths whose content the coverage run measures or builds; a modified one
# makes the reports describe another tree. Covers what bash executes.
readonly SOURCE_PATHSPEC=('*.sh' '*.bats' '*.bash' '*justfile*' '*Dockerfile*')

# The header from `# Usage:` to the first blank line is the help text.
usage() {
  sed -n '/^# Usage:/,/^$/p' "${BASH_SOURCE[0]:-$0}" | sed 's/^# \{0,1\}//'
}

err() { printf '[coverage-badge] %s\n' "$*" >&2; }

# ── Measurement ──────────────────────────────────────────────────────────────

# discover_reports <root> -- print one cobertura path per line: kcov's merged
# report alone, else exactly one per shard directory.
discover_reports() {
  local _root="$1" _dir _xml
  if [[ -f "${_root}/coverage/kcov-merged/cobertura.xml" ]]; then
    printf '%s\n' "${_root}/coverage/kcov-merged/cobertura.xml"
    return 0
  fi
  for _dir in "${_root}"/coverage/*/; do
    [[ -d "${_dir}" ]] || continue
    if [[ -f "${_dir}kcov-merged/cobertura.xml" ]]; then
      printf '%s\n' "${_dir}kcov-merged/cobertura.xml"
      continue
    fi
    while IFS= read -r _xml; do
      printf '%s\n' "${_xml}"
      break
    done < <(find "${_dir}" -name cobertura.xml -type f | sort)
  done
}

# head_epoch <root> -- commit time of HEAD, in seconds.
head_epoch() {
  git -C "$1" log -1 --format=%ct HEAD 2>/dev/null
}

# assert_measures_head <root> <report>... -- fail, with a reason on stderr,
# unless the reports can be shown to describe HEAD's tree.
assert_measures_head() {
  local _root="$1"; shift
  local _head _mtime _report _dirty _stamp_file _stamp _scope _line _sha

  _head="$(head_epoch "${_root}")"
  if [[ -z "${_head}" ]]; then
    err "REFUSING: ${_root} has no HEAD commit, so there is nothing to" \
        "attribute a coverage figure to."
    return 1
  fi

  # Identity: the recorded sha must be HEAD.
  _stamp_file="${_root}/${HEAD_STAMP_REL}"
  if [[ ! -r "${_stamp_file}" ]]; then
    err "REFUSING: the reports under ${_root}/coverage/ carry no" \
        "provenance stamp (${HEAD_STAMP_REL}), so nothing says which tree" \
        "they measured. ${RERUN_HINT}"
    return 1
  fi
  _stamp=""
  _scope=""
  while IFS= read -r _line || [[ -n "${_line}" ]]; do
    if [[ -z "${_stamp}" ]]; then
      _stamp="${_line}"
      continue
    fi
    [[ "${_line}" == scope=* ]] && _scope="${_line#scope=}"
  done < "${_stamp_file}"
  _sha="$(git -C "${_root}" rev-parse HEAD 2>/dev/null)"
  if [[ -z "${_stamp}" || -z "${_sha}" || "${_stamp}" != "${_sha}" ]]; then
    err "REFUSING: the reports were produced from a different commit" \
        "(${_stamp:-<empty>}), not the one being released (${_sha:-<none>})." \
        "${RERUN_HINT}"
    return 1
  fi

  # Completeness: a shard run writes into the same coverage/ tree.
  if [[ -z "${_scope}" ]]; then
    err "REFUSING: the provenance stamp (${HEAD_STAMP_REL}) records no" \
        "scope, so nothing says whether the WHOLE suite produced these" \
        "reports. ${RERUN_HINT} A shard argument narrows the run;" \
        "a whole-suite measurement takes none."
    return 1
  fi
  if [[ "${_scope}" != "full" ]]; then
    err "REFUSING: the reports cover ${_scope}, not the whole suite; a" \
        "partition's rate is not the project's. ${RERUN_HINT}" \
        "A shard argument narrows the run; a whole-suite measurement" \
        "takes none."
    return 1
  fi

  for _report in "$@"; do
    _mtime="$(stat -c %Y "${_report}" 2>/dev/null)"
    if [[ -z "${_mtime}" ]]; then
      err "REFUSING: cannot read the mtime of ${_report}."
      return 1
    fi
    if (( _mtime < _head )); then
      err "REFUSING: ${_report} is older than the commit being released;" \
          "it measured an earlier tree. ${RERUN_HINT}"
      return 1
    fi
  done

  _dirty="$(git -C "${_root}" status --porcelain --untracked-files=no \
    -- "${SOURCE_PATHSPEC[@]}" 2>/dev/null)"
  if [[ -n "${_dirty}" ]]; then
    err "REFUSING: instrumented sources are modified in the worktree, so" \
        "the reports do not describe the tree being released:"
    printf '%s\n' "${_dirty}" >&2
    return 1
  fi

  return 0
}

# measured_rate <report>... -- print the merged project line rate. Exit 1 from
# the gate (below COVERAGE_MIN) still carries a rate; only exit 2 has none.
measured_rate() {
  local _out _rc
  _out="$(_coverage_gate_run "$@" 2>/dev/null)"
  _rc=$?
  if (( _rc >= 2 )); then
    return 1
  fi
  if [[ "${_out}" =~ merged\ line\ rate\ ([0-9.]+)% ]]; then
    printf '%s\n' "${BASH_REMATCH[1]}"
    return 0
  fi
  return 1
}

# ── Rendering ────────────────────────────────────────────────────────────────

# grade_colour <rate> -- the colour for a rate, from shields' flat palette.
grade_colour() {
  awk -v r="$1" 'BEGIN {
    if (r + 0 >= 90) { print "#4c1";     exit }
    if (r + 0 >= 80) { print "#97ca00";  exit }
    if (r + 0 >= 70) { print "#a4a61d";  exit }
    if (r + 0 >= 60) { print "#dfb317";  exit }
    if (r + 0 >= 50) { print "#fe7d37";  exit }
    print "#e05d44"
  }'
}

# render_svg <label> <value> <colour> -- a flat-square badge that loads
# nothing external.
render_svg() {
  local _label="$1" _value="$2" _colour="$3"
  # 7px per character of 11px DejaVu Sans, plus a 12px pad.
  local _lw=$(( ${#_label} * 7 + 12 ))
  local _vw=$(( ${#_value} * 7 + 12 ))
  local _w=$(( _lw + _vw ))
  cat <<SVG
<svg xmlns="http://www.w3.org/2000/svg" width="${_w}" height="20"
     role="img" aria-label="${_label}: ${_value}">
  <title>${_label}: ${_value}</title>
  <rect width="${_lw}" height="20" fill="#555"/>
  <rect x="${_lw}" width="${_vw}" height="20" fill="${_colour}"/>
  <g font-family="DejaVu Sans,Verdana,Geneva,sans-serif" font-size="11"
     fill="#fff" text-anchor="middle">
    <text x="$(( _lw / 2 ))" y="14">${_label}</text>
    <text x="$(( _lw + _vw / 2 ))" y="14">${_value}</text>
  </g>
</svg>
SVG
}

# write_badge <out> <label> <value> <colour> -- render to a temp file and move
# it into place, so a failed render keeps the previous badge.
write_badge() {
  local _out="$1"; shift
  local _tmp
  mkdir -p "$(dirname "${_out}")" || return 1
  _tmp="$(mktemp "${_out}.XXXXXX")" || return 1
  if ! render_svg "$@" > "${_tmp}"; then
    rm -f "${_tmp}"
    return 1
  fi
  mv -f "${_tmp}" "${_out}"
}

# ── Entry ────────────────────────────────────────────────────────────────────

main() {
  # Strict mode here, not at file scope: the file is sourceable.
  set -uo pipefail

  local _root="" _version="" _out="" _unmeasured=0 _line=""
  local -a _reports=()

  # An argument error exits 2; `${2:?...}` would exit 1, the refusal.
  while (( $# > 0 )); do
    case "$1" in
      --repo-root)
        [[ $# -ge 2 && -n "${2:-}" ]] || {
          err "--repo-root expects <path>"; return 2; }
        _root="$2"; shift 2 ;;
      --version)
        [[ $# -ge 2 && -n "${2:-}" ]] || {
          err "--version expects <vX.Y.Z>"; return 2; }
        _version="$2"; shift 2 ;;
      --out)
        [[ $# -ge 2 && -n "${2:-}" ]] || {
          err "--out expects <path>"; return 2; }
        _out="$2"; shift 2 ;;
      --report)
        [[ $# -ge 2 && -n "${2:-}" ]] || {
          err "--report expects <path>"; return 2; }
        _reports+=("$2"); shift 2 ;;
      --unmeasured) _unmeasured=1; shift ;;
      -h|--help)   usage; return 0 ;;
      *)           err "unknown option: $1"; usage >&2; return 2 ;;
    esac
  done

  if [[ -z "${_root}" ]]; then
    _root="$(git rev-parse --show-toplevel 2>/dev/null)"
    if [[ -z "${_root}" ]]; then
      err "not inside a git repo and no --repo-root given"
      return 2
    fi
  fi
  if [[ ! -d "${_root}" ]]; then
    err "no such repo root: ${_root}"
    return 2
  fi
  [[ -n "${_out}" ]] || _out="${_root}/${DEFAULT_OUT_REL}"

  if [[ -z "${_version}" ]]; then
    if [[ -r "${_root}/.version" ]]; then
      read -r _version < "${_root}/.version"
    fi
    if [[ -z "${_version}" ]]; then
      err "no --version given and ${_root}/.version is missing or empty;" \
          "the figure must name the release it belongs to"
      return 2
    fi
  fi

  if (( _unmeasured == 1 )); then
    write_badge "${_out}" "coverage" "not measured (${_version})" "#9f9f9f" \
      || return 2
    printf 'coverage badge: %s -> not measured\n' "${_version}"
    return 0
  fi

  if (( ${#_reports[@]} == 0 )); then
    while IFS= read -r _line; do
      [[ -n "${_line}" ]] && _reports+=("${_line}")
    done < <(discover_reports "${_root}")
  fi
  if (( ${#_reports[@]} == 0 )); then
    err "REFUSING: no coverage report under ${_root}/coverage/." \
        "${RERUN_HINT} The badge is never carried over from the previous" \
        "release."
    return 1
  fi

  assert_measures_head "${_root}" "${_reports[@]}" || return 1

  # shellcheck source=../test/drivers/coverage_gate.sh disable=SC1091
  if ! source "${GATE}"; then
    err "cannot source the coverage gate at ${GATE}"
    return 2
  fi

  local _rate
  _rate="$(measured_rate "${_reports[@]}")"
  if [[ -z "${_rate}" ]]; then
    err "REFUSING: the reports under ${_root}/coverage/ yielded no line" \
        "rate. ${RERUN_HINT}"
    return 1
  fi

  local _value _colour
  _value="$(awk -v r="${_rate}" 'BEGIN{printf "%.1f", r}')%"
  _colour="$(grade_colour "${_rate}")"
  write_badge "${_out}" "coverage" "${_value} (${_version})" "${_colour}" \
    || return 2
  printf 'coverage badge: %s -> %s (%s)\n' "${_version}" "${_value}" "${_out}"
}

if [[ "${BASH_SOURCE[0]:-}" == "${0:-}" ]]; then
  main "$@"
fi
